#!/usr/bin/env python3
"""Reproduce monochrome data-chart and navigation trials from existing evidence."""
from pathlib import Path
import csv,json,collections,datetime,ast,argparse
parser=argparse.ArgumentParser(description=__doc__)
parser.add_argument("--check", action="store_true")
args=parser.parse_args()
generated={}
def emit(path,text):generated[path]=text
R=Path(__file__).resolve().parents[1]; D=R/'book/data/factory-archaeology-260925'; O=R/'book/tikz'
inv={Path(x['source']).stem:x for x in json.loads((O/'inventory.json').read_text())}
def rows(n):return list(csv.DictReader((D/(n+'.csv')).open()))
def esc(s):
 for a,b in [('&',r'\&'),('_',r'\_'),('%',r'\%'),('#',r'\#')]:s=s.replace(a,b)
 return s.replace('->',r'$\rightarrow$')
def coords(rs,key,scale=1):return ' '.join('(%s,%g)'%(r['project_week'],float(r[key])*scale) for r in rs if r[key]!='')
def plot(rs,key,style='',scale=1):return r'\addplot+['+style+'] coordinates {'+coords(rs,key,scale)+'};\n'
def axis(body,options=''):return r'\begin{axis}[mage plot,'+options+']\n'+body+'\\end{axis}\n'
# External annotations retain units, qualifications and source callouts at print size.
chart_notes={
 'f1_realization_over_time':r'Commits per ISO week; project W1 begins 2026-03-09.\\Dotted guides: retrospective stages — W1 feasibility, W4 SaaS,\\W5 formats/standards, W13 hardening, W20 serverless.',
 'f19_delegation_over_time':r'Commits per ISO week; project W1 begins 2026-03-09.\\Human-or-unknown is a residual and overstates human work.',
 'f2_work_over_time':r'Upper: epics created/closed per week. Lower: active epics (cumulative).\\Project W1 begins 2026-03-09.',
 'f7_controls_accumulate':r'Count of files in the repository at each week-end; missing observations omitted.\\Project W1 begins 2026-03-09.',
 'f5_f6_capital_and_support_ratio':r'Upper: lines of code and Markdown, excluding vendor/generated files.\\Lower: support/production ratio; dotted line marks parity (1.0).\\Diamonds: prototype (0.85) and August 3 book snapshot (3.0).',
 'f21_f22_model_census':r'Declared models (n = 130): representation forms above, modeled targets below.',
 'f13_mature_flow_funnel':r'Events in week 2026-W35: 592 started; 573 landed (96.8\%); 10 aborted.\\Workspace retirement is a separate lifecycle count.',
 'f10_what_experience_became':r'Twelve conversion episodes; three up-front confirmations excluded.\\Blocking is deterministic; advisory is probabilistic; measurement adds no hard gate.',
 'churn-per-path':r'Web: Python service/worker. Backend: C\# CLI/rule engine.\\Mechanization backend: +941,120 / −286,378 lines.',
 'velocity-commits-per-week':r'Commits per week; inset reports commit-size quartiles in lines of code.',
}
def write(stem,body,redesign,data):
 if stem in chart_notes:
  body+=r'\node[anchor=north,align=center,text width=13.5cm,font=\fontsize{10}{12}\selectfont,inner sep=0pt] at ([yshift=-16pt]current bounding box.south) {'+chart_notes[stem]+r'};'+'\n'
  redesign+=' Restored external units and interpretive annotations at 10 pt.'
 emit(O/'figures'/f'{stem}.tex','% Generated by tools/mage_tikz_charts.py; edit generator, not coordinates.\n\\begin{tikzpicture}\n'+body+'\\end{tikzpicture}\n')
 a=inv.get(stem,{}); emit(O/'receipts'/f'{stem}.json',json.dumps(dict(source=a.get('source',f'assets/{stem}.svg'),claim=a.get('caption','Book chapter orientation.'),topology='Quantitative axes preserve source values and categories.' if data else 'Seven ordered chapter stations; current chapter filled.',required_terms=[],bw_encoding='Explicit labels, distinct markers and monochrome patterns; no color-only distinction.',redesign=redesign,questions=[],alt=a.get('caption','Seven chapters in order, with current chapter marked.').replace('*','').replace('(left)', '(upper panel)').replace('(right)', '(lower panel)').replace('coloured by enforcement class', 'grouped by enforcement class'),data=data),indent=2)+'\n')
week='xmin=.3,xmax=29.7,xtick={1,5,10,15,20,25,29},xticklabels={W1,W5,W10,W15,W20,W25,W29}'
styles=['draw=black,fill=black!70','draw=black,fill=white,pattern=north east lines','draw=black,fill=white']
r=rows('weekly_factory_metrics')
b=''.join(plot(r,k,s) for k,s in zip(['commits_agent','commits_automation','commits_human_or_unknown'],styles))
for e in rows('events'):
 if e['category']=='build_stage':
  q=next((int(x['project_week']) for x in r if x['iso_week']==e['iso_week']),None)
  if q:b+=r'\draw[dotted] (axis cs:'+str(q)+r',0)--(axis cs:'+str(q)+',4000);\n'
b+=r'\legend{Agent-authored,Automation-integrated,Human or unknown}'
write('f1_realization_over_time',axis(b,week+',ybar stacked,bar width=9pt,ymin=0,ymax=4200,ytick={0,2000,4000},yticklabels={0,2K,4K},legend style={at={(.5,1.15)},anchor=south,legend columns=3}'),'Dotted stage boundaries retained; provenance encoded by solid, hatch, and white bars.', ['weekly_factory_metrics.csv','events.csv'])
b=''.join(plot(r,k,s) for k,s in zip(['epics_created','epics_closed'],styles)) + r'\legend{Created,Closed}'
s=axis(b,week+',name=top,ybar,bar width=4pt,ymin=0,ytick={0,50,100},height=4cm,legend pos=north west')
s+=axis(plot(r,'active_epics_estimate','black,mark=*,mark size=1pt'),week+',at={(top.south west)},anchor=north west,yshift=-1.3cm,height=4cm,ymin=0,ytick={0,400,800}')
s+=r'\node[anchor=west] at (top.north west) [yshift=12pt] {Weekly openings and closures};'+'\n'+r'\node[anchor=west] at (top.south west) [yshift=-24pt] {Active epics (cumulative estimate)};'+'\n'
write('f2_work_over_time',s,'Two vertically aligned panels retain weekly intent and accumulated active estimate.', ['weekly_factory_metrics.csv'])
r=rows('control_growth_weekly'); b=''
for k,s in zip(['lint_files','gate_scripts_ourdef','system_model_py_files'],['black,mark=*','black,dashed,mark=square*','black,dotted,mark=triangle*']):b+=plot(r,k,s+',mark size=1.4pt')
b+=r'\legend{Lint files,Gate/check scripts,System-model files}'
write('f7_controls_accumulate',axis(b,week+',ymin=0,ytick={0,500,1000},legend pos=north west'),'Line patterns and markers distinguish three stock series; missing observations omitted as in source.', ['control_growth_weekly.csv'])
r=rows('delegation_weekly');b=''.join(plot(r,k,s) for k,s in zip(['agent_authored','automation_integrated','human_or_unknown'],styles))+r'\legend{Agent-authored,Automation-integrated,Human or unknown}'
write('f19_delegation_over_time',axis(b,week+',ybar stacked,bar width=9pt,ymin=0,ymax=4000,ytick={0,2000,4000},yticklabels={0,2K,4K},legend style={at={(.5,1.15)},anchor=south,legend columns=3}'),'Same provenance counts; explicit residual is not a measurement of human reading.', ['delegation_weekly.csv'])
r=rows('loc_weekly');cats=['prod_loc','test_loc','controls_loc','orchestration_loc','infra_loc','docs_loc','system_model_loc']; styles7=['fill=black!75','pattern=north east lines','pattern=dots','fill=black!30','pattern=horizontal lines','fill=white','pattern=crosshatch']
b=''.join(plot(r,k,'draw=black,'+st,1e-6) for k,st in zip(cats,styles7))+r'\legend{Production,Tests,Controls,Orchestration,Infrastructure,Docs,System models}'
s=axis(b,week+',name=capital,ybar stacked,bar width=9pt,height=4.5cm,ymin=0,ytick={0,2,4},yticklabels={0,2M,4M},legend style={at={(.5,1.05)},anchor=south,legend columns=4}')
b=plot(r,'support_ratio','black,mark=*,mark size=1pt')+plot(r,'support_ratio_excl_docs','black,dashed,mark=square*,mark size=1pt')
pts=[]
for a in rows('loc_snapshots'):
 if a['support_ratio']:
  d=datetime.date.fromisoformat(a['date']); w=((d-datetime.timedelta(days=d.weekday()))-datetime.date(2026,3,9)).days//7+1;pts.append(f"({w},{a['support_ratio']})")
b+=r'\addplot+[only marks,black,mark=diamond*,mark size=3pt] coordinates {'+' '.join(pts)+r'};'+ '\n'+r'\draw[dotted] (axis cs:1,1)--(axis cs:29,1);\legend{All support,Excluding docs,Book snapshots}'
s+=axis(b,week+',at={(capital.south west)},anchor=north west,yshift=-1.7cm,height=4.5cm,ymin=0,ytick={0,2,4},legend pos=north west')
write('f5_f6_capital_and_support_ratio',s,'Vertical panels increase print legibility. Same seven LoC categories and two ratios; snapshot diamonds and parity preserved.', ['loc_weekly.csv','loc_snapshots.csv'])
def bars(items,extra='',width='8cm'):
 labels=','.join('{'+esc(k)+'}' for k,v in items)
 b=r'\addplot+[draw=black,fill=black!30] coordinates {'+' '.join(f'({v},{i})' for i,(k,v) in enumerate(items))+r'};'
 return axis(b,'xbar,bar width=9pt,width='+width+',height='+str(max(2.3,len(items)*.42))+'cm,xmin=0,ymin=-.7,ymax='+str(len(items)-.3)+',ytick={'+','.join(map(str,range(len(items))))+'},yticklabels={'+labels+'},y dir=reverse,xmajorgrids,ymajorgrids=false,nodes near coords,point meta=x,enlarge x limits={upper,value=.12},'+extra)
r=rows('model_census');forms=collections.Counter(x['form'] for x in r);targets=collections.Counter(x['target'] for x in r)
s=bars(forms.most_common(),'name=forms,xtick={0,25,50}')+bars(targets.most_common(),'at={(forms.south west)},anchor=north west,yshift=-1.5cm,xtick={0,40,80}')
write('f21_f22_model_census',s,'Uses actual CSV census total130; removes stale129 suptitle from old generator. Two panels remain.', ['model_census.csv'])
r=max(rows('mature_flow_weekly'),key=lambda a:int(a['merge_train_complete'] or 0));items=[('Started',int(r['merge_train_started'])),('Landed',int(r['merge_train_complete'])),('Aborted',int(r['merge_train_aborted'])),('Workspaces retired',int(r['tombstone']))]
write('f13_mature_flow_funnel',bars(items,'xtick={0,300,600}'),f"Same maximum-completion week {r['iso_week']}; categorical bars do not imply retirement is a sequential funnel stage.", ['mature_flow_weekly.csv'])
# Reuse the exact historical category and enforcement functions, without importing matplotlib.
src=ast.parse((R/'book/figures/factory-archaeology-260925/f10_what_experience_became.py').read_text()); fn=next(n for n in src.body if isinstance(n,ast.FunctionDef) and n.name=='main'); ns={}
for f in fn.body:
 if isinstance(f,ast.FunctionDef):exec(compile(ast.Module(body=[f],type_ignores=[]),'category-functions','exec'),ns)
rs=[a for a in rows('governance_conversions') if not a['recurrence_classification'].startswith('confirmation')]
groups=['deterministic / blocking','probabilistic / advisory','measurement (deliberately no hard gate)']
labels=[ns['bucket'](a['control_type']) for a in rs]
b=''
for group,shade in zip(groups,[70,35,10]):
 points=' '.join(f'(1,{i})' for i,a in enumerate(rs) if ns['enforcement_class'](a)==group)
 b+=r'\addplot[draw=black,fill=black!'+str(shade)+',bar shift=0pt] coordinates {'+points+r'};'+'\n'
b+=r'\legend{Blocking,Advisory,Measurement}'
s=axis(b,'xbar,bar width=10pt,width=6.5cm,height=10.5cm,xmin=0,xmax=1.4,ymin=-.6,ymax=11.6,xtick={0,1},ytick={'+','.join(map(str,range(12)))+'},yticklabels={'+','.join('{'+esc(label)+'}' for label in labels)+'},y dir=reverse,xmajorgrids,ymajorgrids=false,yticklabel style={text width=6cm,align=right,font=\\magefigurefont\\fontsize{10}{12}\\selectfont},legend style={at={(.5,1.03)},anchor=south,legend columns=3},xlabel={Conversion episodes}')
write('f10_what_experience_became',s,'Restores the original twelve category bars. Three distinct gray fills preserve enforcement classes: 8 blocking, 2 advisory, 2 measurement. Exact original bucketing; three confirmations excluded.', ['governance_conversions.csv'])
# Navigation is a seven-station ordered map; markers, not colour, indicate position.
labels=['The Problem','Modeling','Alignment','MAGE in Motion','Factories','Theory','Profession']
chapter_names=['The New Engineering Problem','Modeling','Alignment','MAGE in Motion: Engineering Through Models','Agentic Software Factories','The Theory','The Profession']
for part in range(1,8):
 s=r'\draw[line width=.7pt] (0,0)--(12.6,0);'+'\n'
 for i,label in enumerate(labels):
  s+=r'\node[circle,draw,fill='+('black' if i+1==part else 'white')+',minimum size='+('10pt' if i+1==part else '6pt')+',inner sep=0pt] at ('+str(i*2.1)+',0) {};\n'
  s+=r'\node[align=center,text width=2cm,anchor=north'+(',font=\\bfseries' if i+1==part else '')+'] at ('+str(i*2.1)+',-.25) {'+label.replace('MAGE in Motion',r'MAGE in\\Motion')+'};\n'
 s+=r'\node[align=center,text width=14cm,font=\bfseries\fontsize{11}{13}\selectfont] at (6.3,1) {\magebookref{part:'+str(part)+'}{Chapter '+str(part)+'} · '+chapter_names[part-1]+r'};'+'\n'
 write(f'nav-subway-p{part}',s,f'Current chapter{part} emphasized with larger solid station and bold label; ordered spine retained; full chapter heading restored.',[])
# Historical plots retain their historical window. Never substitute the newer series.
import re,xml.etree.ElementTree as ET,hashlib
native=(R/'book/latex/sources/appendix-evidence-ledger/evidence-tables.tex').read_text()
vals=[]
for name in ['Prototype','Mechanization','Hardening','Loop management']:
 m=re.search(r'^'+name+r' & ([\d,]+) & ([\d,]+) & ([\d,]+) & ([\d,]+)',native,re.M)
 if not m:raise ValueError('Historical churn table missing '+name)
 vals.append([int(v.replace(',','')) for v in m.groups()])
b=''
for j,style in [(0,'fill=black!65'),(2,'fill=white,pattern=north east lines')]:
 for sign,k in [(1,j),(-1,j+1)]:
  b+=r'\addplot[draw=black,'+style+',bar shift='+('-6pt' if j==0 else '6pt')+(',forget plot' if sign<0 else '')+'] coordinates {'+' '.join(f'({i+1},{sign*v[k]/1000})' for i,v in enumerate(vals))+r'};'+'\n'
b+=r'\legend{Web,Backend}'
write('churn-per-path',axis(b,'xlabel={Additions above zero; deletions below},ybar,bar width=11pt,xmin=.5,xmax=4.5,ymin=-350,ymax=1000,xtick={1,2,3,4},xticklabels={Prototype,Mechanization,Hardening,{Loop management}},ytick={-250,0,500,1000},yticklabels={-250K,0,500K,1M},legend style={at={(.5,1.05)},anchor=south,legend columns=2}'),'One linear scale above and below zero replaces the original unequal positive/negative scales. All16 exact counts from the native evidence table; fills distinguish paths, sign distinguishes additions/deletions.', ['book/latex/sources/appendix-evidence-ledger/evidence-tables.tex'])
# Original matplotlib SVG is the only surviving weekly-series artifact located.
# Recover integer bar counts at sub-1e-4 precision from its explicit calibrated axis.
svg=R/'book/assets/velocity-commits-per-week.svg';tree=ET.parse(svg);ns={'s':'http://www.w3.org/2000/svg'};ax=tree.find('.//s:g[@id="axes_1"]',ns)
baseline=356.24; tick1000=255.424324; recovered=[]
for g in ax.findall('s:g',ns):
 p=g.find('s:path',ns)
 if p is not None and 'fill: #2f5169' in p.get('style',''):
  q=list(map(float,re.findall(r'-?\d+(?:\.\d+)?',p.get('d'))));v=(q[1]-q[5])*1000/(baseline-tick1000)
  if abs(v-round(v))>1e-4:raise ValueError('Historical SVG bar is not recoverable as an integer count')
  recovered.append(round(v))
assert len(recovered)==19
b=r'\addplot[draw=black,fill=black!40] coordinates {'+' '.join(f'({i+1},{v})' for i,v in enumerate(recovered))+r'};'
b+=r'\node[anchor=north west,align=left,fill=white,draw=black!30,rounded corners,inner sep=5pt] at (axis description cs:.03,.97) {Commit size (LOC)\\25th: 28\\Median: 118\\75th: 328};'
write('velocity-commits-per-week',axis(b,'ybar,bar width=13pt,xmin=.5,xmax=19.5,ymin=0,ymax=3600,xtick={1,6,11,16},xticklabels={Mar.12,Apr.16,May21,Jun.25},ytick={1000,2000,3000},yticklabels={1K,2K,3K}'),'Recovers the19 actual bars and quartiles from originalSVG; its description says20weeks but the artwork contains19. Candidate preserves the artwork window; does not manufacture the missing week.', ['book/assets/velocity-commits-per-week.svg'])
p=O/'receipts/velocity-commits-per-week.json';r=json.loads(generated[p]);r['questions']=['Original SVG contains 19 bars despite 20-week description. Confirm whether publisher edition should refresh to 20-week or 29-week evidence; current candidate preserves 19 bars.'];r['recovered_counts']=recovered;r['source_sha256']=hashlib.sha256(svg.read_bytes()).hexdigest();r['recovery_max_error']=1e-4;emit(p,json.dumps(r,indent=2)+'\n')

for path,text in generated.items():
    # The figure review is editorial evidence, separate from the data projection.
    # Preserve that one field while still checking every generated receipt field.
    if path.suffix == '.json' and path.exists():
        previous=json.loads(path.read_text())
        if 'style_review' in previous:
            receipt=json.loads(text)
            receipt['style_review']=previous['style_review']
            text=json.dumps(receipt,indent=2)+'\n'
    if args.check:
        if not path.exists() or path.read_text()!=text:raise SystemExit("Stale chart projection: "+str(path))
    else:
        path.parent.mkdir(parents=True,exist_ok=True)
        path.write_text(text)
print(f"TikZ chart/navigation projections: {len(generated)//2} checked" if args.check else f"Generated {len(generated)//2} TikZ chart/navigation candidates")
